powerpagecomponent.content:
{
  "description": "Allowlist of columns the browser may write on al_reviewinstance. Two trigger columns: al_submitrequested, which SubmitRequestPlugin reads to drive submission; and al_answerrequest, which carries an answer payload consumed by AnswerRequestPlugin because the browser cannot create an al_response directly. Status, submitted-on and the assigned contact stay off the list so the plug-ins remain the sole authority.",
  "value": "al_submitrequested,al_answerrequest"
}
